#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ProjectDriveRefusal {
    Host,
    Refused(String),
    Failed(String),
}

impl ProjectDriveRefusal {
    pub(crate) fn message(&self) -> String {
        match self {
            ProjectDriveRefusal::Host => String::from("a step of the build failed"),
            ProjectDriveRefusal::Refused(why) => why.to_string(),
            ProjectDriveRefusal::Failed(why) => why.to_string(),
        }
    }
}
impl std::fmt::Display for ProjectDriveRefusal {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.message())
    }
}
impl std::error::Error for ProjectDriveRefusal {}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
