pub fn project_drive_no_std_for(triple: &str) -> String { format!("cannot build for `{}`: this toolchain has no `std` for it.\nInstall it with `rustup target add {}`. A machine other than the one this runs on also needs a linker for it, named to Cargo in `$CARGO_HOME/config.toml` (a project's own is not read) as `[target.{}] linker = \"…\"`.", triple, triple, triple) }

