// this was written - see `contracts::sync`.
pub(crate) fn project_drive_cargo_env<H: ProjectDriveHost>(host: &H, link_flags: &[String], no_cache: bool, shared: bool) -> Result<Vec<(String, String)>, Box<dyn std::error::Error>> {
    let mut env = host.settings_env();
    env.push((String::from("NIKAIA_RUSTC_WRAPPER"), String::from("1")));
    env.push((String::from("NIKAIA_GEN_DIR"), nikaia_std::fs::path::to_text(&(host.gen_dir()))?));
    if shared { env.push((String::from("NIKAIA_PROGRAM_TAG"), format!("_{}", host.root_tag()))); }
    env.push((String::from("NIKAIA_LINK_FLAGS"), link_flags.join("\u{1f}")));
    if no_cache { env.push((String::from("NIKAIA_NO_CACHE"), String::from("1"))); }
    match host.shown_as() {
        None => { },
        Some((ref entry, ref written)) => { env.push((String::from("NIKAIA_SHOWN_AS"), format!("{}\u{1f}{}", entry, written))); },
    }
    match host.allowlist()? {
        None => { },
        Some(ref list) => { env.push((String::from("NIKAIA_ALLOW_READ_FROM_LIST"), nikaia_std::fs::path::to_text(&(list))?)); },
    }
    Ok(env)
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn project_drive_c_library<H: ProjectDriveHost>(host: &H, header: &str, python: Option<String>, node: Option<String>, messages: &str) -> Result<(), Box<dyn std::error::Error>> {
    let made = nikaia_std::fs::path::join(&(host.own_dir()), std::path::Path::new(&("c-library")));
    project_drive_make_dir(&made)?;
    let package = nikaia_std::index::or(host.package_name(), || "program".into());
    host.write_if_changed(&nikaia_std::fs::path::join(&(made), std::path::Path::new(&(format!("{}.h", package)))), header)?;
    let bind = nikaia_std::index::or(host.bind(), || "".into());
    if bind == "python" {
        match python {
            None => { },
            Some(ref text) => {
                let module = nikaia_std::fs::path::join(&(made), std::path::Path::new(&(package.replace('-', "_"))));
                project_drive_make_dir(&module)?;
                host.write_if_changed(&nikaia_std::fs::path::join(&(module), std::path::Path::new(&("__init__.py"))), text)?;
                println!("binding: {}", nikaia_std::fs::path::display(&(nikaia_std::fs::path::join(&(module), std::path::Path::new(&("__init__.py"))))));
            },
        }
    }
    if bind == "node" {
        match node {
            None => { },
            Some(ref text) => {
                let module = nikaia_std::fs::path::join(&(made), std::path::Path::new(&("node")));
                project_drive_make_dir(&module)?;
                host.write_if_changed(&nikaia_std::fs::path::join(&(module), std::path::Path::new(&(format!("{}.c", package)))), text)?;
                host.write_if_changed(&nikaia_std::fs::path::join(&(module), std::path::Path::new(&("binding.gyp"))), &cx_node_gyp(&package))?;
                println!("binding: {}", nikaia_std::fs::path::display(&(nikaia_std::fs::path::join(&(module), std::path::Path::new(&(format!("{}.c", package)))))));
            },
        }
    }
    for built in host.libraries_in(messages) {
        let name = match nikaia_std::fs::path::file_name(&(built)) { Some(__nikaia_value) => __nikaia_value, None => continue };
        match fs::copy(&built, &nikaia_std::fs::path::join(&(made), &name), &fs::Root::Anywhere) {
            Ok(_) => {},
            Err(error) => { return Err(nikaia_std::error::raise(ProjectDriveRefusal::Failed(format!("copying {}: {}", nikaia_std::fs::path::display(&(built)), error)), &"project_drive_c_library")); },
        };
    }
    println!("library: {}", nikaia_std::fs::path::display(&(made)));
    Ok(())
}

pub fn project_drive_backend_said(messages: &str) -> bool { messages.lines().any(|line| { line.contains("\"compiler-message\"") }) }

pub trait ProjectDriveKeptHost {
    fn user_cache_dir(&self) -> fs::Path;
    fn use_entry(&self, entry: &std::path::Path);
    fn write_if_changed(&self, path: &std::path::Path, text: &str) -> Result<(), Box<dyn std::error::Error>>;
}

pub fn project_drive_not_the_entry(file: &std::path::Path, root: &std::path::Path, entry: &str) -> String { format!("{} is not the entry point of the project at {}.\n`nikaia run` with a file runs the program whose entry it is, and this project's program starts at `{}`. Run `nikaia run --project {}`, or `nikaia lower {}` to lower the file to Rust.", nikaia_std::fs::path::display(&(file)), nikaia_std::fs::path::display(&(root)), entry, nikaia_std::fs::path::display(&(root)), nikaia_std::fs::path::display(&(file))) }

pub async fn project_drive_kept_for_file<H: ProjectDriveKeptHost>(file: &std::path::Path, entry: &str, host: &H) -> Result<fs::Path, Box<dyn std::error::Error>> {
    let canonical_file = project_members_canonical(file);
    let bytes: Vec<u8> = nikaia_std::fs::path::display(&(canonical_file)).bytes().collect::<Vec<_>>();
    let hex = hash::sha256_hex(&bytes);
    let key: String = hex.chars().take(16).collect();
    let stem = nikaia_std::index::or(match nikaia_std::fs::path::file_name(&(nikaia_std::fs::path::with_extension(&(file), std::path::Path::new(&(""))))).as_ref() {
        Some(__nikaia_it) => Some(nikaia_std::fs::path::display(&(__nikaia_it))),
        None => None,
    }, || "".into()).to_lowercase();
    let first = nikaia_std::index::or(stem.chars().next(), || ' '.into());
    let fits = first >= 'a' && first <= 'z' && stem.chars().all(|c| { c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-' || c == '_' });
    let name = if fits { stem } else { String::from("program") };
    let root = nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(host.user_cache_dir()), std::path::Path::new(&("run")))), std::path::Path::new(&(format!("{}-{}", name, key))));
    host.use_entry(&root);
    host.write_if_changed(&nikaia_std::fs::path::join(&(root), std::path::Path::new(&("nikaia.toml"))), &format!("# Kept by `nikaia run` for {} (ADR-260 D4): a file outside any project\n# is built as one of its own. Rewritten from that file on every run.\n[package]\nname = \"{}\"\nversion = \"0.0.0\"\n", nikaia_std::fs::path::display(&(canonical_file)), name))?;
    let source = match fs::read_to_string(file, &fs::Root::Anywhere).await {
        Ok(value) => value,
        Err(error) => { return Err(nikaia_std::error::raise(ProjectDriveRefusal::Failed(format!("cannot read {}: {}", nikaia_std::fs::path::display(&(file)), error)), &"project_drive_kept_for_file")) },
    };
    host.write_if_changed(&nikaia_std::fs::path::join(&(root), std::path::Path::new(&(entry))), &source)?;
    Ok(root)
}

